def run(n):
    s = '0' + '1' * n + '0'
    while '01' in s or '02' in s or '03' in s:
        if '01' in s:
            s = s.replace('01', '30', 1)
        if '02' in s:
            s = s.replace('02', '101', 1)
        if '03' in s:
            s = s.replace('03', '202', 1)
    return s

best, ans = -1, 0
